?><section class="card"><form method="get" class="filters"><input type="hidden" name="page" value="lab_manage"><label>Approval status<select name="lab_status"><option value="">All statuses</option><?php foreach(['Pending','Approved','Rejected']as $s):?><option <?=$filter===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><button>Filter bookings</button></form><p><?=$count?> booking(s)</p><div class="table-wrap"><table><thead><tr><th>Sl. No.</th><th>Date &amp; time submitted</th><th>Tutor / topic</th><th>Laboratory</th><th>Practical date &amp; time</th><th>Approval status</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=($pn-1)*10+$i+1?></td><td><?=e($r['created_at'])?></td><td><?=e($r['tutor'])?><small><?=e($r['topic'])?></small></td><td><?=e($r['laboratory'])?></td><td><?=e($r['practical_date'])?><small><?=e($r['start_time'].'–'.$r['end_time'])?></small></td><td><span class="badge <?=$r['status']==='Approved'?'good':($r['status']==='Rejected'?'bad':'')?>"><?=e($r['status'])?></span></td><td><a href="?page=lab_manage&id=<?=$r['id']?>#lab-detail">View #<?=$r['id']?></a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7">No bookings match this filter.</td></tr><?php endif;?></tbody></table></div><p>Page <?=$pn?> of <?=$pages?></p><?php foreach(['Previous'=>$pn-1,'Next'=>$pn+1]as $label=>$n)if($n>=1&&$n<=$pages):?><a class="button secondary" href="?<?=e(http_build_query(['page'=>'lab_manage','lab_status'=>$filter,'p'=>$n]))?>"><?=e($label)?></a> <?php endif;?></section>
<?php if($r=one("SELECT * FROM lab_bookings WHERE id=? AND status<>'Deleted'",[(int)($_GET['id']??0)])):?><section class="card" id="lab-detail"><h2>Booking #<?=$r['id']?> · <?=e($r['status'])?></h2><dl class="details"><?php foreach(['tutor'=>'Tutor','email'=>'Email','topic'=>'Practical topic','criteria'=>'Practical criteria','module_name'=>'Module name','module_code'=>'Module code','programme'=>'Programme','study_year'=>'Year','laboratory'=>'Laboratory','practical_date'=>'Practical date','start_time'=>'Start time','end_time'=>'End time','materials'=>'Materials required','created_at'=>'Submitted']as $key=>$label):?><div><dt><?=e($label)?></dt><dd><?=nl2br(e($r[$key]))?></dd></div><?php endforeach;?></dl>
<?php if($user['role']==='admin'):?><details class="lab-delete"><summary>Delete booking</summary><p>Remove this booking from active records and release its time slot. An audit record is retained.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="lab_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="expected_status" value="<?=e($r['status'])?>"><label>Reason for deletion<textarea name="reason" required maxlength="2000" rows="2"></textarea></label><label class="check"><input type="checkbox" name="confirm_delete" value="1" required>I confirm deletion of this booking.</label><button class="danger-button">Delete booking</button></form></details><?php endif;?>
<?php if($r['status']==='Pending'):?><form method="post"><?php csrf();?><input type="hidden" name="action" value="lab_decide"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="form-grid"><?php labField('handled_by','Handled by (technician name)');labField('decision','Decision','select',['Approved','Rejected']);?><label class="full">Decision note / reason for rejection<textarea name="decision_note" rows="3" maxlength="4000"><?=e($_POST['decision_note']??'')?></textarea></label></div><button>Save decision and notify tutor</button></form><?php else:?><p><strong><?=e($r['status'])?></strong> by <?=e($r['handled_by'])?> · <?=e($r['decided_at'])?></p><p><?=nl2br(e($r['decision_note']??''))?></p><?php endif;?></section><?php endif;endif;?>
